278	/// Check if the [`Option`]-wrapped L is same to R.
279	pub fn option_eq<L, R>(left: Option<L>, other: R) -> bool
280	where
281	    L: PartialEq<R>,
282	{
283	    left.is_some_and(|v| v == other)
284	}
