286	/// A container around a static reference that is cheap to clone and hash.
287	#[derive(Debug)]
288	pub struct Static<T: 'static>(pub &'static T);
289	
290	impl<T> Deref for Static<T> {
291	    type Target = T;
292	
293	    fn deref(&self) -> &Self::Target {
294	        self.0
295	    }
296	}
297	
298	impl<T> Copy for Static<T> {}
299	
300	impl<T> Clone for Static<T> {
301	    fn clone(&self) -> Self {
302	        *self
303	    }
304	}
305	
306	impl<T> Eq for Static<T> {}
307	
308	impl<T> PartialEq for Static<T> {
309	    fn eq(&self, other: &Self) -> bool {
310	        std::ptr::eq(self.0, other.0)
311	    }
312	}
313	
314	impl<T> Hash for Static<T> {
315	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
316	        state.write_usize(self.0 as *const T as usize);
317	    }
318	}
